from config import DETAILED_REPORT
from formatting import format_count
from stats import summarize


def report(values):
    result = summarize(values, detailed=DETAILED_REPORT)
    return format_count(result["count"])

def summarize(values, detailed=False):
    result = {"count": len(values)}
    if detailed:
        result["mean"] = sum(values) / len(values)
    return result

import unittest

from app import report
from stats import summarize


class ReportTests(unittest.TestCase):
    def test_empty_plain_report(self):
        self.assertEqual(report([]), "Records: 0")

    def test_populated_plain_report(self):
        self.assertEqual(report([2, 4]), "Records: 2")

    def test_detailed_mean(self):
        self.assertEqual(summarize([2, 4], detailed=True), {"count": 2, "mean": 3})
